import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BUwdTBzS.js";const p=JSON.parse('{"title":"代码安全规则（全局强制）","description":"","frontmatter":{"title":"代码安全规则（全局强制）"},"headers":[],"relativePath":"dev-flow/references/code-safety-rules.md","filePath":"dev-flow/references/code-safety-rules.md","lastUpdated":null}'),a={name:"dev-flow/references/code-safety-rules.md"};function l(c,t,s,n,i,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/code-safety-rules.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="代码安全规则-全局强制" tabindex="-1">代码安全规则（全局强制） <a class="header-anchor" href="#代码安全规则-全局强制" aria-label="Permalink to &quot;代码安全规则（全局强制）&quot;">​</a></h1><blockquote><p>以下规则不仅适用于 dev-flow 步骤 5，而是适用于<strong>任何产生代码文件改动的场景</strong>。</p></blockquote><h2 id="大文件代码移动安全规则-500-行文件强制" tabindex="-1">大文件代码移动安全规则（&gt;500 行文件强制） <a class="header-anchor" href="#大文件代码移动安全规则-500-行文件强制" aria-label="Permalink to &quot;大文件代码移动安全规则（&gt;500 行文件强制）&quot;">​</a></h2><p>在大文件中使用 <code>multi_replace</code> / <code>replace_in_file</code> 进行代码块移动（删除+插入）时，必须遵循：</p><ol><li><strong>唯一性锚点</strong>：<code>old_string</code> 必须包含足够唯一的上下文（≥5 行），避免匹配到文件中其他相同结构的位置（如 <code>&lt;/div&gt;&lt;/Card&gt;</code> 在大文件中可能出现多次）</li><li><strong>分步验证</strong>：代码移动操作拆为「删除」和「插入」两步时，每步完成后立即用 <code>grep_search</code> 确认目标代码的位置和出现次数是否符合预期</li><li><strong>结构完整性验证</strong>：涉及 JSX/TSX 括号结构的移动（如条件渲染块 <code>{ condition &amp;&amp; (...) }</code>），移动后<strong>必须立即运行 TypeCheck</strong>（<code>npx tsc --noEmit 2&gt;&amp;1 | grep &quot;src/&quot;</code>）验证语法完整性，不得跳过</li><li><strong>移动后 Diff 确认</strong>：移动完成后，读取目标位置前后 10 行上下文，确认代码块的上下文衔接正确（括号闭合、缩进一致、无多余/缺失的 <code>}</code>/<code>)</code>）</li></ol><blockquote><p>⚠️ <strong>反模式警示</strong>：</p><ul><li><strong>案例 1</strong>：曾因 <code>old_string</code> 上下文不够唯一，导致 <code>multi_replace</code> 匹配到错误的 <code>&lt;/div&gt;&lt;/Card&gt;</code> 位置，代码被插入到错误区块，且破坏了 JSX 括号结构产生 TS1381 语法错误。</li><li><strong>案例 2</strong>：代码移动完成后未立即运行 TypeCheck，直接向用户汇报完成。用户手动发现 TS1381 错误后才修复——<strong>违反了「代码修改后即时验证规则」</strong>。任何代码结构性改动后必须先验证再汇报。</li></ul></blockquote><h2 id="代码修改后即时验证-审查规则-强制-全局适用" tabindex="-1">代码修改后即时验证+审查规则（强制，全局适用） <a class="header-anchor" href="#代码修改后即时验证-审查规则-强制-全局适用" aria-label="Permalink to &quot;代码修改后即时验证+审查规则（强制，全局适用）&quot;">​</a></h2><blockquote><p>⛔ <strong>全局规则</strong>：此规则适用于<strong>任何产生代码文件改动的场景</strong>——包括步骤 6A 修复、步骤 7 清理/L2 修复、用户临时要求的代码调整、非 dev-flow 流程中的代码修改等。只要修改了代码文件，就必须立即验证并回退到合适的审查步骤。</p></blockquote><p><strong>每次代码修改后</strong>（无论是步骤 5 的正常编码、步骤 6A 的修复、步骤 7 的清理/修复、还是任何中间修复），都必须按顺序执行：</p><h3 id="第一步-即时验证-不可跳过" tabindex="-1">第一步：即时验证（不可跳过） <a class="header-anchor" href="#第一步-即时验证-不可跳过" aria-label="Permalink to &quot;第一步：即时验证（不可跳过）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>改动类型</th><th>必须执行的验证</th></tr></thead><tbody><tr><td>JSX/TSX 结构性改动（移动/删除/插入代码块）</td><td><code>npx tsc --noEmit</code> TypeCheck</td></tr><tr><td>普通代码修改</td><td><code>read_lints</code> 检查改动文件</td></tr><tr><td>样式/CSS 修改</td><td><code>read_lints</code> + 视觉确认（如有 Browser）</td></tr></tbody></table><h3 id="第二步-回退到合适的审查步骤-验证通过后执行" tabindex="-1">第二步：回退到合适的审查步骤（验证通过后执行） <a class="header-anchor" href="#第二步-回退到合适的审查步骤-验证通过后执行" aria-label="Permalink to &quot;第二步：回退到合适的审查步骤（验证通过后执行）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修改发生的阶段</th><th>回退目标</th><th>说明</th></tr></thead><tbody><tr><td>步骤 5 正常编码</td><td>→ 5.5a L1 审查</td><td>正常流程</td></tr><tr><td>步骤 5.5c 修复</td><td>→ 5.5a 重新审查修复代码</td><td>审查修复本身</td></tr><tr><td>步骤 6A V1/V2/V3 修复</td><td>→ 5.5a 审查修复代码</td><td>确保修复不引入新问题</td></tr><tr><td>步骤 6A V4 Browser 修复</td><td>→ 5.5（完整后置钩子）</td><td>功能性修复需完整审查</td></tr><tr><td>步骤 6A V5 Test 修复</td><td>→ 步骤 3 重新制定方案</td><td>测试失败通常涉及方案问题</td></tr><tr><td>步骤 6B 验收修复</td><td>→ 步骤 5（修复后重走 5.5 → 6A → 6B）</td><td>完整回归</td></tr><tr><td>步骤 7 清理调试代码</td><td>→ 5.5c 快速自检</td><td>确认清理未破坏功能</td></tr><tr><td>步骤 7 L2 🔴 修复</td><td>→ 5.5a 审查修复代码 → 5.5c 自检</td><td>修复后重新审查+自检</td></tr><tr><td>非 dev-flow 场景</td><td>验证通过即可</td><td>无 dev-flow 步骤可回退</td></tr></tbody></table><h3 id="禁止行为" tabindex="-1">禁止行为 <a class="header-anchor" href="#禁止行为" aria-label="Permalink to &quot;禁止行为&quot;">​</a></h3><p>❌ <strong>禁止</strong>：修改代码后不验证就进入下一步操作或向用户汇报完成 ❌ <strong>禁止</strong>：连续多次修改后才批量验证——必须每次修改后立即验证 ❌ <strong>禁止</strong>：验证通过后跳过审查直接继续——修复代码本身也需要被审查</p><h2 id="审查报告-验证报告问题定位规范-强制" tabindex="-1">审查报告 / 验证报告问题定位规范（强制） <a class="header-anchor" href="#审查报告-验证报告问题定位规范-强制" aria-label="Permalink to &quot;审查报告 / 验证报告问题定位规范（强制）&quot;">​</a></h2><blockquote><p>以下产出物中，所有「问题定位」字段必须使用可点击链接，按 AI 行为规范「文件/代码位置引用」执行。</p></blockquote><table tabindex="0"><thead><tr><th>产出物</th><th>问题定位格式</th></tr></thead><tbody><tr><td>L1 / L2 / L3 审查报告</td><td><code>`相对路径`</code> L行号</td></tr><tr><td>read_lints / tsc / eslint 报告</td><td>同上</td></tr><tr><td>浏览器运行时错误定位（若有 source map）</td><td>同上</td></tr></tbody></table><p><strong>严禁</strong>：输出裸 src/xxx.tsx:42 或 L42 等无法点击的定位。</p><p><strong>示例（正确）</strong>：</p><table tabindex="0"><thead><tr><th>严重度</th><th>问题定位</th><th>描述</th></tr></thead><tbody><tr><td>🔴 CRITICAL</td><td><code>src/x.tsx</code> L42</td><td>未使用可选链</td></tr><tr><td>🟡 HIGH</td><td><code>src/y.ts</code> L10-L30</td><td>useEffect 缺 cleanup</td></tr></tbody></table>',22)])])}const b=d(a,[["render",l]]);export{p as __pageData,b as default};
